fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = if m > n { m } else { n };

    // Broadcast or clone a
    let broadcast_a = if m == 1 && max_len > 1 {
        vec![a[0]; max_len]  // repeat single element
    } else {
        a.clone()            // lengths are same or 1 == max_len
    };

    // Broadcast or clone b
    let broadcast_b = if n == 1 && max_len > 1 {
        vec![b[0]; max_len]
    } else {
        b.clone()
    };

    (broadcast_a, broadcast_b)
}